call_2_changes.text:
{"changes": [
  {"change": "modified", "requirement_id": "R-008", "new_text": "For reagent based particulate reduction REC the monitoring device shall include the detection of the interruption of the input of any reagent or additive.", "new_paragraph": "7.5.1"},
  {"change": "modified", "requirement_id": "R-037", "new_text": "The reduction efficiency shall be determined by comparison of the emissions measured over the weighted WHTC for REC to be applied to heavy-duty engines or over the weighted NRTC for REC to be applied to non-road mobile machinery or Category T vehicles engines; the reduction efficiency shall be calculated as defined in 8.3.4. of this Regulation.", "new_paragraph": "8.3.2"},
  {"change": "modified", "requirement_id": "R-046", "new_text": "Direct sampling from raw exhaust gas prior to dilution is permitted; the dilution ratios of the particle number diluters (PND1 and PND2 of the particle transfer system, as defined in UN Regulations Nos. 49 and 96) shall then be adapted to the measurement range of the Particle Number Counter (PNC).", "new_paragraph": "8.5.2"},
  {"change": "modified", "requirement_id": "R-050", "new_text": "For Class III and Class IV REC, emissions of ammonia shall not exceed a mean value of 25 ppm when measured using the procedures defined in Appendix 7 to Annex 4 of the 06 series of amendments to UN Regulation No. 49 or in Appendix 7 to Annex 4 of the 05 series of amendment to UN Regulation No. 96.", "new_paragraph": "8.6.2"},
  {"change": "added", "new_text": "The manufacturer shall provide written maintenance instructions to be given by the installer to the driver or operator.", "new_paragraph": "7.9"},
  {"change": "added", "new_text": "The manufacturer shall provide installation documents for the REC.", "new_paragraph": "7.9"},
  {"change": "added", "new_text": "The manufacturer shall provide instructions for an operator warning system, the inducement system and the reagent freeze protection (where applicable) to be given by the installer to the repair-workshop, or the driver or the operator, as appropriate.", "new_paragraph": "7.9"},
  {"change": "added", "new_text": "The manufacturer shall provide a written statement to the installer, to be given to the driver or operator, on the normal operating conditions (temperature range, environmental conditions, …) within which the REC will operate correctly.", "new_paragraph": "7.9"}
]}
